mapper.sql:
WHERE a.workspace_id = #{workspaceId}

    AND a.status = #{status}


    AND a.subject_type = #{subjectType}


    AND a.agent_id = #{agentId}


    AND a.risk = #{risk}


    AND a.create_at >= #{from}


    AND a.create_at <= #{to}


    AND (a.title ILIKE '%' || #{keyword} || '%' OR a.tool_name ILIKE '%' || #{keyword} || '%')



        AND EXISTS (
            SELECT 1 FROM runtime_approval_assignee s
             WHERE s.approval_id = a.id AND s.user_id = #{userId})


        AND a.requested_by = #{userId}

mapper.select:
SELECT
FROM runtime_approval a
ORDER BY a.create_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT

FROM runtime_approval a
WHERE a.id = #{id}
